FILE: app/src/fade-in.ts
```ts
import { createPropertyAnimationClip, createPropertyAnimationGroup } from "@babylonjs/lite";
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";

export function fadeIn(manager: AnimationManager, panel: { alpha: number }, durationMs: number): AnimationGroup {
    const durationS = durationMs / 1000;

    const clip = createPropertyAnimationClip("fadeIn", [
        {
            path: "alpha",
            keys: [
                { time: 0, value: 0 },
                { time: durationS, value: 1 },
            ],
            interpolation: "linear",
        },
    ]);

    return createPropertyAnimationGroup(manager, panel, clip, { loop: false });
}
```

I created `src/fade-in.ts` which builds a two-key linear property-animation clip (alpha 0 → 1 over `durationMs`) and hands it to `createPropertyAnimationGroup` with `loop: false`, so the group attaches to the manager, starts playing immediately, writes `panel.alpha` at a steady rate each update, and stops (setting `isPlaying` to false) once it reaches the end value of 1. I'm not sure of anything; the API and notes are unambiguous for this use case.
